def find_permutations(N, A):
    if N == 3:
        if A[0] == A[1] and A[1] == A[2]:
            return "YES", [1, 2, 3], [2, 3, 1]
        else:
            return "NO", None, None

    B = [0] * N
    C = [0] * N

    for i in range(N):
        B[i] = i + 1
        C[i] = (i + 1) % N + 1

    return "YES", B, C

def main():
    T = int(input())
    results = []

    for _ in range(T):
        N = int(input())
        A = list(map(int, input().split()))

        result, B, C = find_permutations(N, A)
        results.append((result, B, C))

    for result, B, C in results:
        if result == "YES":
            print(result)
            print(*B)
            print(*C)
        else:
            print(result)

if __name__ == "__main__":
